parameters.query:
=SELECT id, title, target_audience, target_industry, core_problem, opportunity_score, recommended_offer, estimated_deal_value_vnd
FROM opportunities
{{ $json?.body?.opportunity_id ? "WHERE id = '" + $json.body.opportunity_id + "'" : "ORDER BY (CASE WHEN status IN ('IDENTIFIED', 'PLANNED') THEN 1 ELSE 2 END), opportunity_score DESC, created_at DESC" }}
LIMIT 1;

parameters.jsCode:
// ── Hợp nhất thông tin đầu vào & đóng gói AI Payload cho bài viết Facebook & Campaign ──
let webhookData = {};
try {
  webhookData = $('Generate Campaign Webhook').first()?.json?.body || {};
} catch (e) {
  webhookData = {};
}

let topOpp = {};
try {
  topOpp = $('Fetch Top Opportunity').first()?.json || {};
} catch (e) {
  topOpp = {};
}

const opportunityId = webhookData.opportunity_id || topOpp.id || null;
const title = webhookData.title || topOpp.title || 'Chuyển đổi số & Thiết kế Website cao cấp';
const targetIndustry = webhookData.target_industry || topOpp.target_industry || 'Doanh nghiệp SME & Startups';
const coreProblem = webhookData.core_problem || topOpp.core_problem || 'Website cũ lỗi thời, tải chậm và tỷ lệ chuyển đổi đơn hàng thấp';
const recommendedOffer = webhookData.recommended_offer || topOpp.recommended_offer || 'Gói thiết kế Website doanh nghiệp chuẩn quốc tế với Next.js & UI/UX độc bản';

const systemInstruction = `Bạn là Giám đốc Content Marketing & Ad Strategist của S.T.A.R.K — Digital Design & Web Studio (Website chính thức: https://company-plum-rho.vercel.app/).
Hãy tạo 01 bài viết Facebook bán hàng & marketing hoàn chỉnh (kèm hình ảnh mockup UI/UX độc quyền) và 01 bản đề xuất chiến dịch Paid Ads.

Yêu cầu bài viết Facebook (full_post_content):
- Tiêu đề giật tít thu hút (Hook)
- Đánh trúng nỗi đau thực tế của khách hàng (ngành ${targetIndustry})
- Đưa ra giải pháp Web Engineering vượt trội của S.T.A.R.K (Next.js siêu tốc, UI/UX độc bản, bảo mật, chuẩn SEO, tích hợp AI)
- Kêu gọi hành động (CTA) rõ ràng kèm đường link Portfolio chính thức: https://company-plum-rho.vercel.app/ và Hotline/Zalo tư vấn: 0845.663.357
- Thêm icon emoji sinh động, định dạng xuống dòng chuyên nghiệp, đính kèm hashtags.

Trả về ONLY valid JSON với cấu trúc:
{
  "campaign_name": "STARK_FB_POST_...",
  "platform": "FACEBOOK",
  "objective": "LEAD_GENERATION",
  "facebook_post": {
    "headline": "Tiêu đề bài viết ngắn gọn",
    "hook": "Câu mở đầu gây chú ý",
    "full_post_content": "Toàn bộ nội dung bài viết hoàn chỉnh sẵn sàng đăng lên Facebook...",
    "call_to_action": "Nhận tư vấn & Demo"
  },
  "ad_copies": {
    "variation_a": {
      "hook_angle": "Trực diện nỗi đau website cũ mất khách",
      "headline": "Website tải chậm đang làm bạn mất khách?",
      "primary_text": "Hơn 70% khách hàng rời bỏ website nếu tốc độ tải trang quá 3 giây...",
      "call_to_action": "Nhận tư vấn & Demo"
    },
    "variation_b": {
      "hook_angle": "Đòn bẩy công nghệ & Trải nghiệm UI/UX chuẩn quốc tế",
      "headline": "Thiết kế Website độc bản chuẩn Silicon Valley",
      "primary_text": "Tối ưu tỷ lệ chuyển đổi, bảo mật tuyệt đối và tốc độ vượt trội...",
      "call_to_action": "Xem Portfolio"
    }
  },
  "target_audience_spec": {
    "locations": ["Hà Nội", "TP. Hồ Chí Minh", "Đà Nẵng"],
    "age_range": "26 - 52",
    "job_titles": ["Founder", "CEO", "Giám đốc", "Marketing Manager", "Chủ doanh nghiệp"],
    "interests": ["Thiết kế web", "Digital Marketing", "Kinh doanh B2B", "Chuyển đổi số"]
  },
  "creative_direction": "Dark mode UI screen mockup showing Next.js high speed performance",
  "proposed_daily_budget_vnd": 500000,
  "max_total_budget_vnd": 7000000,
  "expected_cpl_vnd": 180000
}`;

const userContent = `Bối cảnh cơ hội kinh doanh:
- Tiêu đề: ${title}
- Ngành hàng mục tiêu: ${targetIndustry}
- Vấn đề cốt lõi: ${coreProblem}
- Gói giải pháp S.T.A.R.K đề xuất: ${recommendedOffer}`;

const aiRequestBody = {
  systemInstruction: { parts: [{ text: systemInstruction }] },
  contents: [{ parts: [{ text: userContent }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    maxOutputTokens: 4096,
    temperature: 0.3
  }
};

return [{
  json: {
    opportunity_id: opportunityId,
    title: title,
    target_industry: targetIndustry,
    core_problem: coreProblem,
    recommended_offer: recommendedOffer,
    ai_request_body: aiRequestBody
  }
}];

// ── Bóc tách dữ liệu Campaign & Facebook Post ──────────────────────────
let inputContext = {};
try {
  inputContext = $('Prepare Campaign Context').first()?.json || {};
} catch(e) {}

let rawAi = $input.first()?.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
if (!rawAi && $input.first()?.json?.text) {
  rawAi = $input.first().json.text;
}

let plan = null;
if (rawAi) {
  let cleaned = String(rawAi).trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  }
  try {
    plan = JSON.parse(cleaned);
  } catch (e) {
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { plan = JSON.parse(jsonMatch[0]); } catch (err) {}
    }
  }
}

if (!plan) {
  const oppTitle = inputContext.title || 'Corporate Web Growth';
  plan = {
    campaign_name: `STARK_FB_${oppTitle.toUpperCase().replace(/[^A-Z0-9]/g, '_').substring(0, 25)}_Q3`,
    platform: 'FACEBOOK',
    objective: 'LEAD_GENERATION',
    facebook_post: {
      headline: 'Giải pháp Website Chuẩn Quốc Tế Cho Doanh Nghiệp Tăng Trưởng',
      hook: 'Website cũ lỗi thời đang làm bạn đánh mất hàng ngàn khách hàng tiềm năng?',
      full_post_content: `🚀 NÂNG CẤP DIỆN MẠO SỐ — BỨT PHÁ DOANH THU CÙNG S.T.A.R.K\n\n${inputContext.core_problem || 'Website tải chậm, trải nghiệm người dùng kém khiến tỷ lệ chuyển đổi đơn hàng sụt giảm nghiêm trọng.'}\n\n💡 S.T.A.R.K mang đến giải pháp Web Engineering & Digital Design chuẩn quốc tế:\n- Thiết kế UI/UX độc bản, tối ưu từng điểm chạm khách hàng\n- Công nghệ Next.js siêu tốc, tải trang < 1.5s\n- Chuẩn SEO Google, bảo mật tuyệt đối\n\n📁 Xem Portfolio dự án: https://company-plum-rho.vercel.app/\n📞 Hotline/Zalo tư vấn (24/7): 0845.663.357`,
      call_to_action: 'Nhận tư vấn ngay'
    },
    ad_copies: {
      variation_a: {
        hook_angle: 'Trực diện nỗi đau website cũ mất khách',
        headline: 'Website chuẩn quốc tế cho doanh nghiệp',
        primary_text: `Giải quyết dứt điểm: ${inputContext.core_problem || 'Website tải chậm'}. Nâng cấp ngay cùng S.T.A.R.K.`,
        call_to_action: 'Nhận tư vấn ngay'
      }
    },
    target_audience_spec: {
      locations: ['Hà Nội', 'TP. Hồ Chí Minh', 'Đà Nẵng'],
      age_range: '28 - 50',
      job_titles: ['CEO', 'Founder', 'CMO', 'Giám đốc']
    },
    creative_direction: 'Dark mode UI screen mockup',
    proposed_daily_budget_vnd: 500000,
    max_total_budget_vnd: 7000000,
    expected_cpl_vnd: 180000
  };
}

// Đảm bảo có full_post_content
let fbPostContent = plan.facebook_post?.full_post_content || '';
if (!fbPostContent) {
  const varA = plan.ad_copies?.variation_a || {};
  fbPostContent = `🚀 ${varA.headline || plan.facebook_post?.headline || 'GIẢI PHÁP THIẾT KẾ WEBSITE CHUẨN QUỐC TẾ'}\n\n${varA.primary_text || plan.facebook_post?.hook || inputContext.core_problem || ''}\n\n💡 ${inputContext.recommended_offer || 'Gói thiết kế website cao cấp với Next.js & UI/UX độc bản từ S.T.A.R.K'}\n\n📁 Portfolio chính thức: https://company-plum-rho.vercel.app/\n📞 Hotline/Zalo: 0845.663.357`;
}

return [{
  json: {
    opportunity_id: inputContext.opportunity_id || null,
    campaign_name: plan.campaign_name || 'STARK_GROWTH_POST',
    platform: plan.platform || 'FACEBOOK',
    objective: plan.objective || 'LEAD_GENERATION',
    facebook_post: plan.facebook_post || {},
    post_content: fbPostContent,
    ad_copies: plan.ad_copies || {},
    target_audience_spec: plan.target_audience_spec || {},
    creative_direction: plan.creative_direction || '',
    proposed_daily_budget_vnd: Number(plan.proposed_daily_budget_vnd) || 500000,
    max_total_budget_vnd: Number(plan.max_total_budget_vnd) || 7000000,
    expected_cpl_vnd: Number(plan.expected_cpl_vnd) || 180000
  }
}];

